R.append((3702868,"बेक्ड पास्ता","यह आपके पास पहले से मौजूद किसी भी आकार के पास्ता के साथ काम करता है, हालाँकि ऑरज़ो विशेष रूप से अच्छा है।","2",None,
["1 बड़ा चम्मच वनस्पति तेल","½ छोटा प्याज़, छिला और कटा हुआ","150g पास्ता (ऑरज़ो अच्छा रहता है)","40g स्प्रिंग ग्रीन्स या जमा हुआ पालक","½ शिमला मिर्च, बीज निकालकर कटी हुई","1 छोटा चम्मच सूखी मिश्रित जड़ी-बूटियाँ","½ छोटा चम्मच मिर्च के फ़्लेक्स (वैकल्पिक)","1 बड़ा चम्मच टमाटर प्यूरी","400g का छोले का डिब्बा (पानी निथारा हुआ)","1 कम नमक वाला सब्ज़ी स्टॉक क्यूब, उबलते पानी से 150ml तक बनाया हुआ","10g बिना नमक का मक्खन","20g चेडर, कद्दूकस किया हुआ"],
["ओवन को 180°C पर पहले से गरम करें। ओवन-सेफ़ बर्तन में तेल गरम करें और प्याज़ डालें। नरम होने तक पकाएँ। एक अलग बर्तन में, पास्ता को पैकेट के निर्देशों के अनुसार पकाएँ।","तले जा रहे प्याज़ में हरी पत्तेदार सब्ज़ी, शिमला मिर्च, जड़ी-बूटियाँ और मिर्च डालें। मध्यम आँच पर 5 मिनट नरम होने तक पकाएँ। टमाटर प्यूरी डालें और एक मिनट और पकाएँ।","पका हुआ और पानी निथारा हुआ पास्ता, छोले और स्टॉक डालें और उबाल आने दें। बर्तन पर ढक्कन लगाएँ और 15 मिनट के लिए ओवन में रखें।","ओवन से निकालें, मक्खन मिलाएँ, ऊपर से चीज़ कद्दूकस करें और परोसें।"],
[[CH,"यह संतोषजनक एक-बर्तन वाला व्यंजन नमक, पोटैशियम और फ़ॉस्फ़ेट में कम है।"],[CB,"इस रेसिपी में पास्ता कार्बोहाइड्रेट का मुख्य स्रोत है, और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"सामग्री की मात्रा और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है, और इसलिए उन लोगों के लिए उपयुक्त है जिन्हें कम पोटैशियम वाला आहार लेने की सलाह दी गई है।\nयह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, जो छोलों और चीज़ से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो निर्देशानुसार लें।"],[PR,"इस रेसिपी में कुछ प्रोटीन है। यदि आपको प्रोटीन घटाने की सलाह दी गई है तो आप कम चीज़ या कम छोले उपयोग करना चाह सकते हैं।"],[TP,"यह व्यंजन आपके पास पहले से मौजूद किसी भी आकार के पास्ता के साथ काम करता है, हालाँकि ऑरज़ो विशेष रूप से अच्छा है। यदि आप पास्ता की जगह चावल उपयोग करना चाहें, तो आपको थोड़े और स्टॉक की ज़रूरत पड़ सकती है।"],[ST,"यह व्यंजन तुरंत खाना सबसे अच्छा है।"]],
[]))
R.append((3712518,"बेसिक कीमा और मसूर मिश्रण","बीफ़ और मसूर का यह मिश्रण केवल मांस वाले संस्करण की तुलना में न सिर्फ़ अधिक किफ़ायती है, बल्कि अधिक सेहतमंद भी है।","5 परोसे (प्रत्येक परोसा दो लोगों के लिए)",None,
["625g बीफ़ कीमा","2 बड़े प्याज़, छिले और बारीक कटे हुए","250g लाल मसूर","2 बड़े चम्मच टमाटर प्यूरी","1 कम नमक वाला बीफ़ या सब्ज़ी स्टॉक क्यूब","800ml उबलता पानी","2 छोटे चम्मच वनस्पति तेल"],
["एक बड़े नॉन-स्टिक बर्तन को मध्यम आँच पर गरम करें और वनस्पति तेल डालें। कटे हुए प्याज़ डालें और 6 से 8 मिनट नरम होने तक पकाएँ।","कीमा और प्याज़ के मिश्रण में मसूर, स्टॉक और टमाटर प्यूरी डालें। उबाल आने दें, फिर आँच धीमी करें और धीमी आँच पर 25 मिनट पकाएँ।","पक जाने पर, कीमा और मसूर के मिश्रण को उपयोग के लिए 5 हिस्सों में बाँट लें।"],
[[CH,"एक बार बन जाने के बाद, इस बहुमुखी रेसिपी को पाई के भरावन, करी, स्टर फ़्राई या पास्ता सॉस बनाने के आधार के रूप में उपयोग किया जा सकता है।"],[CB,"इस व्यंजन में मसूर कार्बोहाइड्रेट का मुख्य स्रोत है। मान उन लोगों के लिए दिए गए हैं "+INS],[PP,"बीफ़ कीमा के कुछ हिस्से की जगह मसूर डालने से फ़ॉस्फ़ेट की मात्रा कम करने में मदद मिली है, लेकिन यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो आपको फिर भी इस व्यंजन के साथ उसे लेना चाहिए।"],[PR,"इस व्यंजन में बीफ़ और मसूर प्रोटीन के मुख्य स्रोत हैं। यह व्यंजन प्रोटीन का अच्छा स्रोत है और इसलिए उस व्यक्ति के लिए उपयुक्त है जिसे अधिक प्रोटीन वाले आहार की ज़रूरत है।"],[ST,"एक साथ बड़ी मात्रा में पकाने से पैसे और समय दोनों बच सकते हैं, क्योंकि कई खाद्य पदार्थ सुपरमार्केट में बड़ी मात्रा में खरीदने पर अधिक किफ़ायती होते हैं। इस मिश्रण के हिस्सों को फ्रिज में 2 दिन तक रखा जा सकता है या एकल या दोहरे हिस्सों में 3 महीने तक फ़्रीज़ किया जा सकता है। उपयोग से पहले अच्छी तरह पिघलाएँ।"]],
[]))
R.append((3763636,"बचे हुए ब्रेड से गाजर का केक","यह केक बचे हुए ब्रेड का स्वादिष्ट उपयोग करके एक भरपूर, कम पोटैशियम वाला व्यंजन बनाता है।","10",None,
[["गाजर का केक","400g ब्रेड (सफ़ेद या साबुत गेहूँ), फाड़ी हुई"],["गाजर का केक","100g मुलायम हल्की ब्राउन शुगर"],["गाजर का केक","1 अंडा"],["गाजर का केक","100g फ़ुल फ़ैट दही"],["गाजर का केक","50g वनस्पति तेल"],["गाजर का केक","2 छोटे चम्मच पिसी दालचीनी"],["गाजर का केक","1 छोटा चम्मच बाइकार्बोनेट ऑफ़ सोडा (बेकिंग सोडा)"],["गाजर का केक","1 छोटा चम्मच वनीला एक्सट्रैक्ट"],["गाजर का केक","1 संतरे का छिलका (कद्दूकस किया हुआ)"],["गाजर का केक","90g गाजर, कद्दूकस की हुई"],["गाजर का केक","90g किशमिश"],["पैशनफ़्रूट कर्ड","1 अंडे की जर्दी"],["पैशनफ़्रूट कर्ड","1 बड़ा चम्मच कैस्टर शुगर (बारीक चीनी)"],["पैशनफ़्रूट कर्ड","100g पैशन फ़्रूट का रस"],["पैशनफ़्रूट कर्ड","15g बिना नमक का मक्खन"],["पैशनफ़्रूट कर्ड","1 बड़ा चम्मच कॉर्नफ़्लोर"],["मस्कारपोन क्रीम","100g डबल क्रीम"],["मस्कारपोन क्रीम","100g मस्कारपोन चीज़, मुलायम किया हुआ"],["मस्कारपोन क्रीम","25g आइसिंग शुगर"],["मस्कारपोन क्रीम","1 छोटा चम्मच वनीला एसेंस"],["परोसने के लिए","½ छोटा चम्मच दालचीनी"],["परोसने के लिए","1 छोटा चम्मच संतरे के छिलके के पतले टुकड़े"]],
["ओवन को 175°C / 145°C फ़ैन / गैस मार्क 4 पर पहले से गरम करें और 11” x 8.5” की आयताकार बेकिंग ट्रे में चिकनाई लगाएँ और मैदा छिड़कें। फाड़ी हुई ब्रेड को फ़ूड प्रोसेसर में डालें और बारीक चूरा होने तक पीसें। चीनी, अंडा, दही, तेल, पिसी दालचीनी, बेकिंग सोडा और वनीला एक्सट्रैक्ट डालें और चिकना होने तक ब्लेंड करें। मिक्सिंग बाउल में डालें और संतरे का छिलका, गाजर और किशमिश बराबर मिलने तक मिलाएँ। केक के मिश्रण को बेकिंग ट्रे में डालें और सींक साफ़ निकलने तक 25-30 मिनट बेक करें।","पैशनफ़्रूट कर्ड: अंडे की जर्दी और चीनी को एक साथ फेंटें और कटोरे में एक तरफ़ रख दें। एक भारी तले वाले सॉसपैन में पैशन फ़्रूट का रस और मक्खन को तब तक धीरे-धीरे गरम करें जब तक मक्खन पिघल न जाए, फिर धीरे-धीरे कॉर्नफ़्लोर मिलाएँ और लगातार चलाते रहें ताकि गुठलियाँ न बनें। मिश्रण को आँच से उतारें और उसके कुछ बड़े चम्मच कटोरे में अंडे के मिश्रण में फेंटें। फेंटना जारी रखें, एक बार में मिश्रण के कुछ बड़े चम्मच अंडे के मिश्रण में डालते हुए।","जब दोनों मिश्रण पूरी तरह मिल जाएँ, तो इसे वापस सॉसपैन में डालें और धीमी से मध्यम आँच पर रखें, लगातार चलाते हुए ताकि अंडे फटें या जमें नहीं। कर्ड के गाढ़ा होने तक 5-8 मिनट पकाएँ। आँच से उतारें और बारीक जाली की छलनी से कटोरे में छान लें। कर्ड की सतह पर सीधे क्लिंग फ़िल्म लगाकर ढकें और उपयोग से पहले कम से कम 2 घंटे फ्रिज में रखें।","जब केक बेक हो जाए और सींक साफ़ निकले, तो ओवन से निकालें और वायर ट्रे पर ले जाने से पहले 10 मिनट ठंडा होने दें ताकि वह ठंडा होता रहे।","मस्कारपोन क्रीम: एक मिक्सिंग बाउल में मस्कारपोन चीज़ और डबल क्रीम को चिकना और मलाईदार होने तक फेंटें। धीरे-धीरे आइसिंग शुगर और वनीला एक्सट्रैक्ट डालें और अच्छी तरह मिलने तक फेंटना जारी रखें।","केक के ठंडा होने पर, उसे 20 चौकोर टुकड़ों में काटें। केक के 10 चौकोर टुकड़ों के किनारों पर क्रीम पाइप करें और बीच में थोड़ा कर्ड भरें। बाकी 10 चौकोर टुकड़े ऊपर रखें और बची हुई क्रीम से सजाएँ। अंत में दालचीनी और संतरे के छिलके छिड़कें। स्वाद विकसित होने के लिए केक को रात भर ठंडी जगह या फ्रिज में भी रहने दें।"],
[[CH,"क्रीम चीज़ आइसिंग और पैशनफ़्रूट कर्ड के साथ एक स्वादिष्ट रूप से नम गाजर का केक। आनंद लें!"],[CB,"इस रेसिपी में ब्रेड कार्बोहाइड्रेट का मुख्य स्रोत है, और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"दी गई मात्रा और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है, इसलिए उन लोगों के लिए यह एक उपयुक्त व्यंजन है जिन्हें अपने आहार में पोटैशियम घटाने की सलाह दी गई है।\nयह रेसिपी फ़ॉस्फ़ेट में अधिक है, इसलिए इसका आनंद कभी-कभार के व्यंजन के रूप में लें, और यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो निर्देशानुसार लें।"],[PR,"यह रेसिपी प्रोटीन में कम है, इसलिए यदि आपको कम प्रोटीन खाने की सलाह दी गई है तो यह कभी-कभार के व्यंजन के रूप में उपयुक्त है।"],[CO,"पैशन फ़्रूट का रस मिलना कठिन हो सकता है। इसके बजाय, आम या अनानास पर विचार करें (इनमें सेब या संतरे के रस की तुलना में पोटैशियम कम होता है)।"],[GF,"ग्लूटेन-मुक्त ब्रेड का उपयोग करें"],[HO,"इस रेसिपी में वसा अधिक है और बेकिंग सोडा से नमक की मध्यम मात्रा है, और इसका आनंद केवल कभी-कभार, स्वस्थ संतुलित आहार के हिस्से के रूप में लेना चाहिए।"],[ST,"पकने और ठंडा होने के बाद, इस रेसिपी को हवाबंद डिब्बे में फ्रिज में 3 दिन तक रखा जा सकता है।"]],
[]))
R.append((3765080,"चिकन और संतरे का सलाद","एक हल्का भोजन, जो कैलोरी और पोटैशियम में कम है लेकिन दिलचस्प स्वाद से भरपूर है।","4",None,
["1 छोटा चम्मच जैतून का तेल","200g चिकन ब्रेस्ट, एक निवाले जितने टुकड़ों में कटा हुआ","215g का छोले का डिब्बा (130g पानी निथारा हुआ) या 150g एडामेमे फलियाँ","400g राइस नूडल्स","2 लिटिल जेम लेट्यूस","2 संतरे, छिले और फाँकों में बँटे हुए","2 नीबू, कद्दूकस किया छिलका",["तिल के तेल की ड्रेसिंग","1 बड़ा चम्मच तिल का तेल"],["तिल के तेल की ड्रेसिंग","2 नीबू का रस"],["तिल के तेल की ड्रेसिंग","1 बड़ा चम्मच कम नमक वाली सोया सॉस"],["तिल के तेल की ड्रेसिंग","1 छोटा चम्मच तिल, भुने हुए"]],
["एक उथले बर्तन में तेल गरम करें और चिकन के टुकड़ों को मध्यम आँच पर तलें। लगभग पक जाने पर, छोले डालें और गरम होने और कुरकुरे होने तक पकाएँ। चिकन के पूरी तरह पक जाने पर, उसे निकालें और अतिरिक्त तेल हटाने के लिए किचन पेपर पर निथार दें (यदि एडामेमे फलियों का उपयोग कर रहे हैं तो उन्हें बाद में डालें)।","जब चिकन पक रहा हो, तब राइस नूडल्स को पैकेट के निर्देशों के अनुसार पकाएँ, फिर पानी निथार दें। ड्रेसिंग के लिए, सभी सामग्री को अच्छी तरह मिलने तक फेंटें और ज़रूरत तक एक तरफ़ रख दें।","लेट्यूस की पत्तियाँ अलग करें, बड़ी पत्तियों को आधा फाड़ दें। लेट्यूस को नूडल्स, संतरे की फाँकों, नीबू के छिलके और एडामेमे फलियों (यदि छोलों की जगह उपयोग कर रहे हों) के साथ मिलाएँ।","चिकन और छोलों को सलाद में मिलाएँ और चार कटोरों में बाँटें। हर परोसे पर तिल के तेल की ड्रेसिंग डालें, फिर परोसें।"],
[[CH,"सेहतमंद हल्के भोजन के लिए एक झटपट और आसान रेसिपी।"],[CB,"इस रेसिपी में राइस नूडल्स कार्बोहाइड्रेट का मुख्य स्रोत हैं, और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"ताज़े संतरे और सलाद के उपयोग के बावजूद यह रेसिपी पोटैशियम में कम है। इसका कारण यह है कि मात्रा न्यूनतम रखी गई है, इसलिए कृपया सभी सामग्री और परोसे के आकार की मात्रा का पालन करना सुनिश्चित करें।\nयह रेसिपी फ़ॉस्फ़ेट में अधिक है, जो चिकन और फलियों से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो निर्देशानुसार लें।"],[PR,"यह रेसिपी प्रोटीन में अधिक है, जो इसे उन लोगों के लिए उपयुक्त बनाती है जिन्हें अधिक प्रोटीन खाने की सलाह दी गई है, विशेष रूप से डायलिसिस ले रहे लोगों के लिए। यदि आपको प्रोटीन घटाने की सलाह दी गई है, तो चिकन को घटाकर 150g कर दें या शाकाहारी/वीगन विकल्प चुनें।"],[GF,"सोया सॉस की जगह टैमारी जैसा ग्लूटेन-मुक्त विकल्प उपयोग करें।"],["शाकाहारी/वीगन","चिकन की जगह पानी निथारा हुआ 400g छोले या बटर बीन्स का एक डिब्बा डालें।"],[HO,"सोया सॉस के उपयोग के बावजूद यह रेसिपी नमक में कम है। हम कम नमक वाली किस्म उपयोग करने की सलाह देते हैं, हालाँकि यह फिर भी नमक में अधिक है इसलिए बताई गई मात्रा का पालन अवश्य करें।"],[ST,FRESH],[TP,"यदि एडामेमे फलियों का उपयोग कर रहे हैं, तो इन्हें जमी हुई खरीदा जा सकता है। पहले उन्हें फ्रिज में पिघलाएँ।"]],
[]))
R.append((3802558,"बेक्ड सेब","यह बेक्ड सेब रेसिपी एक भरपूर और स्वादिष्ट फलों वाली मिठाई बनाती है जो पोटैशियम और फ़ॉस्फ़ेट में कम है।","4",None,
["4 मिठाई वाले सेब (उदाहरण के लिए गाला, ब्रेबर्न, पिंक लेडी, कॉक्स, गोल्डन डिलीशियस)","50g बिना नमक का मक्खन, मुलायम किया हुआ","80-100g ब्लूबेरी (ताज़ी या जमी हुई और पिघलाई हुई)","15g हल्की मुलायम ब्राउन शुगर"],
["ओवन को 180°C / 160°C/ गैस मार्क 4 पर गरम करें। एप्पल कोरर की मदद से सेब का बीच का हिस्सा निकालें और भरने के लिए खुला हिस्सा थोड़ा बड़ा बनाएँ।","मुलायम मक्खन, ब्लूबेरी और चीनी को मिलने तक मिलाएँ, और फिर चारों सेबों के खोखले हिस्सों में भरें।","सेबों को एक छोटी रोस्टिंग डिश में रखें और डिश में 4 बड़े चम्मच पानी डालें।","सेबों के आकार के अनुसार 25-30 मिनट बेक करें, जब तक वे नरम और कैरामलाइज़ न हो जाएँ। थोड़ी डबल क्रीम या सोया वनीला आइसक्रीम के साथ परोसें।"],
[[CH,"आपके संडे रोस्ट खाने के बाद यह बेक्ड सेब की मिठाई बहुत अच्छी लगती है।"],[CB,"इस व्यंजन में कार्बोहाइड्रेट के मुख्य स्रोत सेब और चीनी हैं। कार्बोहाइड्रेट के मान उन लोगों के लिए दिए गए हैं "+INS],[PP,"दी गई मात्रा का पालन करने पर यह मिठाई पोटैशियम और फ़ॉस्फ़ेट में कम है, इसलिए आहार प्रतिबंधों का पालन करते हुए आप इसका आनंद एक विशेष व्यंजन के रूप में ले सकते हैं।"],[PR,"यह मिठाई प्रोटीन में कम है इसलिए कम प्रोटीन वाले आहार का पालन करते समय कभी-कभार के व्यंजन के रूप में इसका आनंद लिया जा सकता है।"],[VG,"वीगन मक्खन और या तो वीगन डबल क्रीम या सोया आइसक्रीम का उपयोग करें।"],[HO,"इस रेसिपी में वसा अधिक है, जो मक्खन और क्रीम से आती है। वसा घटाने के लिए, मक्खन की जगह कम वसा वाले स्प्रेड का उपयोग करें या कम मक्खन का उपयोग करें (उदाहरण के लिए, आधी मात्रा उपयोग करें)। आप क्रीम की जगह हाफ़-फ़ैट क्रेम फ्रेश या सादा सोया योगर्ट भी उपयोग कर सकते हैं।"],[ST,"इस रेसिपी को ताज़ा खाना सबसे अच्छा है।"],[TP,"सेब एक दिन पहले तैयार किए जा सकते हैं। बस उन्हें ढकें और बेक करने के लिए तैयार होने तक फ्रिज में ठंडा रखें।"]],
[]))
R.append((3815833,"चिकन और सब्ज़ियों की लज़ान्या","यह रेसिपी प्रोटीन का बेहतरीन स्रोत है और सब्ज़ियों से मिलने वाली अतिरिक्त अच्छाई से भरपूर है।","4",None,
["300g बिना त्वचा और बिना हड्डी की चिकन जाँघ के फ़िलेट, टुकड़ों में कटे हुए","2 छोटे या 1 बड़ा प्याज़, छिला और बारीक कटा हुआ","4 लहसुन की कलियाँ, छिली और कुचली हुई","400g का कटे टमाटर का डिब्बा","2 छोटे चम्मच सूखी अजवायन (ओरेगैनो)","9 सूखी लज़ान्या शीट","1 बड़ा चम्मच जैतून का तेल","100g गाजर, छिली और बारीक कटी हुई","100g पालक",["सफ़ेद सॉस","20g कॉर्नफ़्लोर"],["सफ़ेद सॉस","25g बिना नमक का मक्खन"],["सफ़ेद सॉस","150ml चिकन स्टॉक, बिना नमक के चिकन स्टॉक क्यूब के ¼ भाग से बना हुआ"],["सफ़ेद सॉस","300ml दूध"],["सफ़ेद सॉस","पिसी काली मिर्च"],["सफ़ेद सॉस","2 छोटे चम्मच पिसा जायफल"],["सफ़ेद सॉस","40g कद्दूकस किया मोज़ेरेला"],["ड्रेसिंग","1 बड़ा चम्मच जैतून का तेल"],["ड्रेसिंग","2 छोटे चम्मच सिरका"],["ड्रेसिंग","2 छोटे चम्मच डिजॉन सरसों"],["ड्रेसिंग","पिसी काली मिर्च"],["परोसने के लिए","200g मिश्रित सलाद की पत्तियाँ"]],
["सफ़ेद सॉस बनाने के लिए एक छोटे बर्तन में मध्यम आँच पर मक्खन पिघलाएँ और फिर कॉर्नफ़्लोर और जायफल फेंटकर मिलाएँ, 2 मिनट पकाएँ। गुठलियों से बचने के लिए लगातार फेंटते हुए धीरे-धीरे दूध और चिकन स्टॉक डालें। गाढ़ा होने तक मध्यम आँच पर रखें। आँच से उतारें और एक तरफ़ रख दें।","एक फ्राइंग पैन में आधा जैतून का तेल मध्यम-तेज़ आँच पर गरम करें और चिकन को हर तरफ़ से भूरा होने तक पकाएँ। पैन से निकालें और एक तरफ़ रख दें। पैन में बचा हुआ तेल गरम करें और प्याज़ और गाजर को नरम होने तक पकाएँ, लहसुन और अजवायन डालें और 2 मिनट और पकाएँ। पालक की पत्तियों को एक अलग सॉसपैन में रखें और ऊपर थोड़ा उबलता पानी डालें। 1 मिनट या पालक के पूरी तरह मुरझाने तक पकाएँ, फिर आँच से उतारें। पालक का पानी छलनी से निथारें, फिर ठंडे पानी से धोएँ और अतिरिक्त पानी निचोड़ लें। टमाटर, पालक और चिकन को गाजर और प्याज़ के साथ फ्राइंग पैन में डालें, उबाल आने दें और 5 मिनट पकाएँ।","ओवन को 180°C/गैस मार्क 6 पर गरम करें। बेकिंग डिश के तले में सफ़ेद सॉस का एक तिहाई भाग फैलाएँ, ऊपर आधा चिकन मिश्रण रखें। 4 ½ लज़ान्या शीट रखें, ऊपर सफ़ेद सॉस का एक और तिहाई भाग और बाकी चिकन मिश्रण डालें। फिर बची हुई लज़ान्या शीट रखें और ऊपर सफ़ेद सॉस डालें। ऊपर से मोज़ेरेला छिड़कें। 40 मिनट पकाएँ।","सभी सामग्री को एक कटोरे में डालकर और फेंटकर ड्रेसिंग बनाएँ।","लज़ान्या को ओवन से निकालें और मिश्रित सलाद और ड्रेसिंग के साथ परोसें।"],
[[CH,"पारंपरिक लज़ान्या का एक सेहतमंद रूप, यह स्वादिष्ट रेसिपी पूरे परिवार के लिए एकदम सही है।"],[CHILD,KIDTXT],[CB,"इस रेसिपी में लज़ान्या शीट कार्बोहाइड्रेट का मुख्य स्रोत हैं, और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"पालक और टमाटर जैसी कुछ उच्च पोटैशियम वाली सामग्री के उपयोग के बावजूद, सामग्री की मात्रा, पकाने की विधि और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है। इसलिए, यह उन लोगों के लिए उपयुक्त है जिन्हें अपने आहार में पोटैशियम घटाने की सलाह दी गई है।\nयह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, जो मुख्य रूप से चिकन, दूध और चीज़ से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो निर्देशानुसार लें। फ़ॉस्फ़ेट को और कम करने के लिए, आप रेसिपी में चीज़ की मात्रा घटाने पर विचार कर सकते हैं।"],[PR,"यह रेसिपी प्रोटीन में अधिक है, इसलिए उन लोगों के लिए उपयुक्त है जिन्हें अधिक प्रोटीन खाने की सलाह दी गई है, जैसे डायलिसिस ले रहे लोग। यदि आपको कम प्रोटीन खाने की सलाह दी गई है तो आप चिकन की मात्रा घटाकर 150g कर सकते हैं और तोरी, गाजर और ब्रोकली जैसी और सब्ज़ियाँ डालकर देख सकते हैं।"],["ऊर्जा","यदि आपको वज़न बढ़ाना है, आपका बढ़ता बच्चा है जिसे अधिक कैलोरी चाहिए, या भूख कम लगती है, तो आप सफ़ेद सॉस बनाने के लिए और मक्खन डाल सकते हैं या कैलोरी बढ़ाने के लिए फ़ुल क्रीम दूध उपयोग कर सकते हैं।"],[GF,"ग्लूटेन-मुक्त लज़ान्या का उपयोग करें"],[VT,"शाकाहारी विकल्प के लिए चिकन की जगह 300-400g टोफ़ू या सोया मीट का उपयोग करने पर विचार करें।"],[VG,"मक्खन, दूध और चीज़ के लिए डेयरी-रहित विकल्पों का उपयोग करने पर विचार करें।"],[HO,"अधिक सेहतमंद विकल्प के लिए साबुत गेहूँ की लज़ान्या शीट का उपयोग करने पर विचार करें।"],[CO,"इस रेसिपी की लागत को यथासंभव कम रखा गया है।"],[ST,"पकने और ठंडा होने के बाद, इस रेसिपी को फ्रिज में रखा जा सकता है और अगले दिन दोबारा गरम किया जा सकता है। दोबारा गरम करते समय सुनिश्चित करें कि यह खूब गरम हो।"]],
[]))
